        &&& self.fc_clients.key() == tid
        &&& self.fc_clients.instance_id() == fc_inst.id()
        &&& self.fc_clients.value().is_Waiting()
        &&& self.batch_perms.is_none()
        &&& self.local_updates.is_none()
